// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.agenticimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Agentic critic. * * After each step, the critic evaluates the result and decides whether the * workflow should: *   - **CONTINUE** — proceed to the next step (planner will decide what) *   - **RETRY** — re-execute the same step (with same params) *   - **STOP** — end the workflow (success or failure) * * ## Evaluation Logic * *   - [AgenticStepResult.FinalAnswerProduced] → STOP (workflow complete) *   - [AgenticStepResult.ToolSuccess] → CONTINUE (let planner decide next) *   - [AgenticStepResult.LlmSuccess] → CONTINUE *   - [AgenticStepResult.ToolFailure] with retryable=true → RETRY (up to maxRetries) *   - [AgenticStepResult.ToolFailure] with retryable=false → CONTINUE (let *     planner decide what to do — it might try a different tool) *   - [AgenticStepResult.LlmFailure] with retryable=true → RETRY *   - [AgenticStepResult.LlmFailure] with retryable=false → STOP (workflow failed) * * ## Constitutional Guardrails * * Before evaluating a step, the critic runs [ConstitutionalGuardrails.check] * on the step. If blocked (harmful pattern, dangerous tool, prompt injection), * the critic returns STOP with FAILED status — the step is NEVER executed. * * ## Retry Logic * * The critic tracks retry count per step. If the same step is retried more * than [maxRetriesPerStep] times (default 2), the critic forces CONTINUE * (let the planner try a different approach) instead of retrying again. * * ## Privacy * * The critic doesn't see user data — it only sees step results, which are * already scrubbed by the executor. * * @see <a href="docs/spec/module2-spec-review.pdf">§9.2 Critic</a> */@Singletonclass AgenticCritic @Inject constructor(    private val maxRetriesPerStep: Int,    private val constitutionalGuardrails: ConstitutionalGuardrails,) {    init {        require(maxRetriesPerStep in 0..5) {            "maxRetriesPerStep must be 0-5, was $maxRetriesPerStep"        }    }    // Track retry count per step number    private val retryCountByStep = java.util.concurrent.ConcurrentHashMap<Int, Int>()    /**     * Check whether [step] is safe to execute (constitutional guardrails).     *     * Called by [AgenticOrchestrator] BEFORE executing the step. If blocked,     * the orchestrator stops the workflow immediately.     *     * @return [GuardrailResult.Safe] or [GuardrailResult.Blocked]     */    fun checkSafety(step: AgenticStep): GuardrailResult {        return constitutionalGuardrails.check(step)    }    /**     * Check whether [userInput] is safe to start a workflow for.     *     * Called by [AgenticOrchestrator] before starting the ReAct loop.     */    fun checkInputSafety(userInput: String): GuardrailResult {        return constitutionalGuardrails.checkInput(userInput)    }    /**     * Evaluate a step result and decide the next action.     *     * @param stepNumber which step was just executed (1-indexed)     * @param step the step that was executed     * @param result the result of executing that step     * @return [CriticDecision] telling the orchestrator what to do next     */    fun evaluate(        stepNumber: Int,        step: AgenticStep,        result: AgenticStepResult,    ): CriticDecision {        return when (result) {            is AgenticStepResult.FinalAnswerProduced -> {                Timber.tag("NOUS.L5").v("Critic: final answer produced → STOP")                CriticDecision.Stop(                    reason = "Final answer produced",                    finalAnswer = result.answer,                    status = WorkflowStatus.COMPLETED,                )            }            is AgenticStepResult.ToolSuccess -> {                Timber.tag("NOUS.L5").v("Critic: tool success → CONTINUE")                CriticDecision.Continue            }            is AgenticStepResult.LlmSuccess -> {                Timber.tag("NOUS.L5").v("Critic: LLM success → CONTINUE")                CriticDecision.Continue            }            is AgenticStepResult.ToolFailure -> {                if (result.retryable) {                    val retries = retryCountByStep.getOrDefault(stepNumber, 0)                    if (retries < maxRetriesPerStep) {                        retryCountByStep[stepNumber] = retries + 1                        Timber.tag("NOUS.L5").w(                            "Critic: tool failure (retryable) → RETRY (%d/%d)",                            retries + 1, maxRetriesPerStep,                        )                        CriticDecision.Retry                    } else {                        Timber.tag("NOUS.L5").w(                            "Critic: tool failure but max retries hit → CONTINUE (let planner try different approach)"                        )                        CriticDecision.Continue                    }                } else {                    Timber.tag("NOUS.L5").w(                        "Critic: tool failure (non-retryable) → CONTINUE (let planner try different approach)"                    )                    CriticDecision.Continue                }            }            is AgenticStepResult.LlmFailure -> {                if (result.retryable) {                    val retries = retryCountByStep.getOrDefault(stepNumber, 0)                    if (retries < maxRetriesPerStep) {                        retryCountByStep[stepNumber] = retries + 1                        Timber.tag("NOUS.L5").w(                            "Critic: LLM failure (retryable) → RETRY (%d/%d)",                            retries + 1, maxRetriesPerStep,                        )                        CriticDecision.Retry                    } else {                        Timber.tag("NOUS.L5").w("Critic: LLM failure, max retries hit → STOP")                        CriticDecision.Stop(                            reason = "LLM query failed after $maxRetriesPerStep retries: ${result.error}",                            finalAnswer = null,                            status = WorkflowStatus.FAILED,                        )                    }                } else {                    Timber.tag("NOUS.L5").w("Critic: LLM failure (non-retryable) → STOP")                    CriticDecision.Stop(                        reason = "LLM query failed (non-retryable): ${result.error}",                        finalAnswer = null,                        status = WorkflowStatus.FAILED,                    )                }            }        }    }    /**     * Reset retry tracking (called when a workflow starts).     */    fun reset() {        retryCountByStep.clear()    }    companion object {        /** Default max retries per step (2 = try the step up to 3 times total). */        const val DEFAULT_MAX_RETRIES_PER_STEP = 2    }}/** * Critic's decision about what to do next. */sealed interface CriticDecision {    /** Proceed to the next step (planner will decide what). */    data object Continue : CriticDecision    /** Re-execute the same step (with same params). */    data object Retry : CriticDecision    /** End the workflow. */    data class Stop(        val reason: String,        val finalAnswer: String?,        val status: WorkflowStatus,    ) : CriticDecision}